const employeeNav = [['dashboard','▦','Dashboard'],['profile','◉','My Profile'],['attendance','◷','Attendance'],['leave','⌁','Leave'],['payroll','₹','Payroll'],['notifications','●','Notifications']]
const hrNav = [['dashboard','▦','Dashboard'],['employees','♧','Employees'],['attendance','◷','Attendance'],['leave','⌁','Leave Approvals'],['payroll','₹','Payroll'],['reports','▤','Reports'],['notifications','●','Notifications'],['settings','⚙','Settings']]

function escape(value = '') { return String(value).replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char])) }
function date(value) { return value ? new Intl.DateTimeFormat(undefined,{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value)) : '—' }
function number(value) { return value === undefined || value === null ? '—' : new Intl.NumberFormat().format(value) }
function initials(name = '') { return name.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase() || 'DF' }
function status(value = '') { const key = String(value).toLowerCase(); const color = /approved|present|active|paid/.test(key) ? 'green' : /rejected|absent|inactive/.test(key) ? 'red' : /pending|leave|half/.test(key) ? 'amber' : 'blue'; return `<span class="status ${color}">${escape(value || 'Draft')}</span>` }
const collections = { Employee:'employees', Attendance:'attendance', 'Leave Application':'leave', 'Salary Slip':'payroll', 'Notification Log':'notifications' }
async function pause() { await new Promise(resolve => setTimeout(resolve, 180)) }
async function api(path, options = {}) {
  await pause()
  const body = options.body ? JSON.parse(options.body) : {}
  const match = decodeURIComponent(path).match(/\/api\/resource\/([^/?]+)(?:\/([^?]+))?/)
  if (!match) return {}
  const list = store[collections[match[1]]]
  if (options.method === 'POST') { const name = match[1] === 'Employee' ? `DF-2026-${String(store.employees.length + 1).padStart(4,'0')}` : `${match[1].slice(0,3).toUpperCase()}-${Date.now()}`; const item={name,...body}; if(match[1] === 'Employee') { item.employee_name=`${body.first_name||''} ${body.last_name||''}`.trim(); item.status='Active' } if(match[1] === 'Leave Application') { const employee=store.employees.find(e=>e.name===body.employee); Object.assign(item,{employee_name:employee?.employee_name||'You',total_leave_days:1,status:'Pending',posting_date:new Date().toISOString().slice(0,10)}) } list.unshift(item); return item }
  if (options.method === 'PUT') { const item=list.find(x=>x.name===match[2]); Object.assign(item,body); return item }
  if (match[2]) return list.find(x=>x.name===match[2])
  return list
}
async function resource(doctype) { await pause(); return store[collections[doctype]] || [] }
async function method(name) { await pause(); if(name === 'hrms.api.get_current_user_info') return {full_name:state.user,roles:state.role==='HR'?['HR Manager']:['Employee']}; if(name === 'hrms.api.get_current_employee_info') return state.employee; if(name === 'hrms.api.get_leave_applications') return store.leave; if(name === 'hrms.api.get_leave_balance_map') return {'Paid Leave':{remaining_leaves:12},'Sick Leave':{remaining_leaves:5}}; if(name === 'hrms.api.mark_all_notifications_as_read'){store.notifications.forEach(n=>n.read=1);return true} return true }
function navigate(page) { state.page = page; location.hash = page; state.menu=false; state.modal=null; render() }
function notify(message) { state.toast = message; render(); setTimeout(()=>{state.toast='';render()}, 3000) }
function roleIsHR() { return state.role === 'HR' }

async function boot() { render() }
function authView() { return `<main class="auth"><section class="auth-card"><div class="brand"><span class="brand-mark">d</span>Dayflow</div><h1>${state.page === 'signup' ? 'Create your workspace access' : 'Welcome back'}</h1><p class="subtle">Every workday, perfectly aligned.</p>${state.page === 'signup' ? signupForm() : signinForm()}</section></main>` }
function signinForm() { return `<form id="signin"><div class="field"><label>Email</label><input required type="email" name="usr" value="hr@dayflow.local" autocomplete="email" /></div><div class="field"><label>Password</label><input required type="password" name="pwd" value="Dayflow@123" autocomplete="current-password" /></div><div id="auth-error"></div><button class="primary wide" type="submit">Sign in</button></form><p class="auth-footer">Need access? <span class="link" data-nav="signup">Create an account</span></p><p class="hint">Frontend preview credentials are pre-filled. No Frappe backend or Docker setup is required.</p>` }
function signupForm() { return `<form id="signup"><div class="two"><div class="field"><label>Employee ID</label><input required name="employee_id" /></div><div class="field"><label>Role</label><select name="role"><option>Employee</option><option>HR</option></select></div></div><div class="field"><label>Email</label><input required type="email" name="email" /></div><div class="field"><label>Password</label><input required minlength="12" type="password" name="password" /><small>At least 12 characters. Use upper-case, lower-case, number and symbol.</small></div><div id="auth-error"></div><button class="primary wide" type="submit">Create account</button></form><p class="auth-footer">Already have an account? <span class="link" data-nav="login">Sign in</span></p>` }
function shell(content, title) { const nav = roleIsHR() ? hrNav : employeeNav; return `<div class="app-shell"><aside class="side ${state.menu?'open':''}"><div class="brand"><span class="brand-mark">d</span>Dayflow</div><p class="tagline">Every workday, perfectly aligned.</p><nav class="nav">${nav.map(([id,i,label])=>`<button class="${state.page===id?'active':''}" data-nav="${id}"><span class="icon">${i}</span>${label}</button>`).join('')}</nav><div class="sidebar-note"><b>${roleIsHR()?'HR workspace':'Employee workspace'}</b><br/>Role-aware records and actions only.</div></aside><section class="workspace"><header class="top"><button class="secondary menu-toggle" data-action="menu">☰</button><div class="crumbs">Dayflow / <b>${title}</b></div><div class="top-actions"><button class="bell" data-nav="notifications" aria-label="Notifications">●<span class="count">${state.data.unread || 0}</span></button><button class="avatar" data-action="profile-menu">${initials(state.employee?.employee_name || state.user)}</button>${state.menu === 'profile' ? `<div class="profile-menu"><button data-nav="profile">My profile</button><button data-action="logout">Log out</button></div>` : ''}</div></header><main class="page">${state.loading?'<div class="loading-line"></div>':''}${content}</main></section></div>${state.modal||''}${state.toast?`<div class="toast">${escape(state.toast)}</div>`:''}` }
function pageHead(title, description, actions='') { return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>` }
function empty(text, action='') { return `<div class="empty">${escape(text)}${action ? `<br/><button class="primary" style="margin-top:10px" data-action="${action}">Create record</button>` : ''}</div>` }
function panel(title, body, action='') { return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>` }

async function loadDashboard() {
  if (state.data.dashboardLoaded) return
  state.loading=true; render()
  const today = new Date().toISOString().slice(0,10)
  try {
    if (roleIsHR()) {
      const [employees, attendance, leaves, slips] = await Promise.all([resource('Employee',{fields:['name','status'],limit_page_length:1000}),resource('Attendance',{fields:['name','status'],filters:[['attendance_date','=',today]],limit_page_length:1000}),resource('Leave Application',{fields:['name','status'],filters:[['status','=','Open'],['docstatus','=',1]],limit_page_length:1000}),resource('Salary Slip',{fields:['name','net_pay'],limit_page_length:1000})])
      state.data.dashboard = { employees:employees.data||employees, attendance:attendance.data||attendance, leaves:leaves.data||leaves, slips:slips.data||slips }
    } else {
      const [attendance, leaves, balances, notices] = await Promise.all([resource('Attendance',{fields:['name','status','in_time','out_time','working_hours','attendance_date'],filters:[['employee','=',state.employee?.name],['attendance_date','=',today]]}),method('hrms.api.get_leave_applications',{limit:5}).catch(()=>[]),method('hrms.api.get_leave_balance_map').catch(()=>({})),resource('Notification Log',{fields:['name','subject','creation','read'],limit_page_length:5}).catch(()=>[])])
      state.data.dashboard = { attendance:(attendance.data||attendance)[0], leaves:leaves.data||leaves, balances, notices:notices.data||notices }
    }
    state.data.dashboardLoaded=true
  } catch (error) { state.data.dashboardError=error.message }
  state.loading=false; render()
}
function dashboard() { setTimeout(loadDashboard); const d=state.data.dashboard||{}; if(roleIsHR()){const a=d.attendance||[];const count=(name)=>a.filter(x=>x.status===name).length;return shell(`${pageHead('HR Dashboard','Today’s workforce view and operational actions.',`<button class="primary" data-action="add-employee">Add employee</button>`)}<div class="grid stats">${[['Total employees',(d.employees||[]).length],['Present today',count('Present')],['Absent today',count('Absent')],['On leave',count('On Leave')],['Pending leave',(d.leaves||[]).length]].map(([x,y])=>`<div class="stat"><small>${x}</small><strong>${number(y)}</strong></div>`).join('')}</div><div class="layout-2 grid" style="margin-top:14px">${panel('Attendance summary', a.length?`<div class="panel-body"><div class="notice">${count('Present')} present · ${count('Absent')} absent · ${count('Half Day')} half-day · ${count('On Leave')} on leave</div></div>`:empty(state.data.dashboardError||'No attendance records for today.'))}${panel('Quick actions',`<div class="quick"><button data-nav="employees"><span>♧</span>Employees</button><button data-nav="attendance"><span>◷</span>Attendance</button><button data-nav="leave"><span>⌁</span>Leave approvals</button><button data-nav="payroll"><span>₹</span>Payroll</button></div>`)}${panel('Payroll summary',`<div class="panel-body"><b>${(d.slips||[]).length} salary slips</b><br/><span class="subtle">Use Payroll to review salary structures and completed slips.</span></div>`)}</div>`,'Dashboard')}
  const attendance=d.attendance; const balanceTotal=Object.values(d.balances||{}).reduce((sum,x)=>sum+Number(x?.remaining_leaves||0),0);return shell(`${pageHead('Dashboard','Your workday at a glance.',`<button class="primary" data-nav="attendance">${attendance?.in_time&&!attendance?.out_time?'Check out':'Check in'}</button>`)}<div class="grid stats">${[['Today',attendance?.status||'Not marked'],['Check in',attendance?.in_time ? new Date(attendance.in_time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '—'],['Check out',attendance?.out_time ? new Date(attendance.out_time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) : '—'],['Working hours',attendance?.working_hours||'—'],['Leave balance',balanceTotal]].map(([x,y])=>`<div class="stat"><small>${x}</small><strong>${escape(y)}</strong></div>`).join('')}</div><div class="layout-2 grid" style="margin-top:14px">${panel('Quick actions',`<div class="quick"><button data-nav="profile"><span>◉</span>Profile</button><button data-nav="attendance"><span>◷</span>Attendance</button><button data-action="apply-leave"><span>⌁</span>Apply leave</button><button data-nav="payroll"><span>₹</span>Payroll</button></div>`)}${panel('Recent activity',d.notices?.length?`<div class="panel-body">${d.notices.map(n=>`<div class="activity"><i class="dot"></i><div>${escape(n.subject)}<br/><small>${date(n.creation)}</small></div></div>`).join('')}</div>`:empty(state.data.dashboardError||'No recent activity.'))}${panel('Recent leave requests',d.leaves?.length?`<div class="panel-body">${d.leaves.map(l=>`<div class="activity"><i class="dot"></i><div>${escape(l.leave_type)} · ${date(l.from_date)} to ${date(l.to_date)}<br/>${status(l.status)}</div></div>`).join('')}</div>`:empty('No leave requests yet.','apply-leave'))}</div>`,'Dashboard') }

async function loadList(kind) { const maps={employees:['Employee',['name','employee_name','department','designation','status','date_of_joining']],attendance:['Attendance',['name','employee','employee_name','attendance_date','status','working_hours']],leave:['Leave Application',['name','employee_name','leave_type','from_date','to_date','total_leave_days','status','posting_date']],payroll:['Salary Slip',['name','employee_name','start_date','end_date','net_pay','status']]}; const [doctype,fields]=maps[kind]; state.loading=true;render();try { const results=await resource(doctype,{fields,limit_page_length:50,order_by:'modified desc'});state.data[kind]=results.data||results }catch(error){state.data[`${kind}Error`]=error.message}state.loading=false;render() }
function listPage(kind,title,desc) { setTimeout(()=>loadList(kind)); const rows=state.data[kind]; const columns={employees:[['name','Employee ID'],['employee_name','Employee name'],['department','Department'],['designation','Designation'],['status','Status'],['date_of_joining','Joining date']],attendance:[['employee_name','Employee'],['attendance_date','Date'],['status','Status'],['working_hours','Working hours']],leave:[['employee_name','Employee'],['leave_type','Leave type'],['from_date','From'],['to_date','To'],['total_leave_days','Duration'],['status','Status']],payroll:[['employee_name','Employee'],['start_date','Period start'],['end_date','Period end'],['net_pay','Net salary'],['status','Status']]}[kind];const primary=kind==='employees'?'add-employee':kind==='leave'?(roleIsHR()?null:'apply-leave'):null;return shell(`${pageHead(title,desc,primary?`<button class="primary" data-action="${primary}">${kind==='employees'?'Add employee':'Apply for leave'}</button>`:'')}<div class="toolbar"><input class="search" placeholder="Search ${title.toLowerCase()}" data-search="${kind}"/><button class="filter" data-action="filter">Filter ▾</button><div class="chips">${kind==='attendance'?'<span class="chip">Current month ×</span>':''}</div></div><div class="table-wrap"><table><thead><tr>${columns.map(([,name])=>`<th>${name} ↕</th>`).join('')}<th></th></tr></thead><tbody>${rows?.length?rows.map(row=>`<tr data-open="${kind}" data-id="${escape(row.name)}">${columns.map(([key])=>`<td>${key==='status'?status(row[key]):key.includes('date')?date(row[key]):escape(row[key]??'—')}</td>`).join('')}<td>›</td></tr>`).join(''):`<tr><td colspan="${columns.length+1}">${state.data[`${kind}Error`] ? escape(state.data[`${kind}Error`]) : 'Loading records…'}</td></tr>`}</tbody></table></div><div class="pager"><span>${rows?.length||0} records</span><span>Previous &nbsp; Next</span></div>` ,title) }
function attendancePage(){return listPage('attendance','Attendance',roleIsHR()?'Review attendance across the organisation.':'Track your attendance and working time.')}
function leavePage(){return listPage('leave',roleIsHR()?'Leave Approvals':'Leave',roleIsHR()?'Review, approve or reject submitted leave requests.':'Leave balance, requests and approval status.')}
function payrollPage(){return listPage('payroll','Payroll',roleIsHR()?'Review salary slips and payroll records.':'Your salary structure and salary slips are read-only.')}

async function employeeDetail(name){state.loading=true;render();try{state.data.employeeDetail=await api(`/api/resource/Employee/${encodeURIComponent(name)}`)}catch(e){state.data.employeeError=e.message}state.loading=false;render()}
function employeesPage(){return listPage('employees','Employees','Manage employee records, profiles and employment details.')}
function detailPage(name){setTimeout(()=>employeeDetail(name));const e=state.data.employeeDetail?.data||state.data.employeeDetail;if(!e)return shell(`${pageHead('Employee','Loading employee record.')}<div class="panel">${empty(state.data.employeeError||'Loading employee…')}</div>`,'Employees');const editable=roleIsHR();return shell(`${pageHead('Employee',e.name)}<section class="detail-top"><div class="photo">${initials(e.employee_name)}</div><div><h2>${escape(e.employee_name)}</h2><p>${escape(e.designation||'No designation')} · ${escape(e.department||'No department')} · ${status(e.status)}</p></div><div class="actions">${editable?`<button class="primary" data-action="edit-employee">Edit</button>`:''}<button class="secondary" data-nav="employees">Back</button></div></section><div class="tabs"><button class="active">Personal</button><button>Job</button><button>Salary</button><button>Documents</button><button>History</button></div>${documentSection('Personal information',[['Name',e.employee_name],['Email',e.user_id||e.company_email||e.personal_email],['Phone',e.cell_number],['Address',e.current_address||e.permanent_address],['Profile picture',e.image?'Uploaded':'Not uploaded']])}${documentSection('Job details',[['Employee ID',e.name],['Department',e.department],['Designation',e.designation],['Joining date',date(e.date_of_joining)],['Employment type',e.employment_type],['Reporting manager',e.reports_to]])}${documentSection('Salary',[['Salary structure','Available in salary assignment'],['Earnings','View salary slip'],['Deductions','View salary slip'],['Net salary','View salary slip']])}`,'Employees')}
function documentSection(title,fields){return `<section class="doc-section"><h3>${title}</h3><div class="fields">${fields.map(([x,y])=>`<div class="read-field"><small>${x}</small><span>${escape(y||'—')}</span></div>`).join('')}</div></section>`}
function profilePage(){const e=state.employee||{};return shell(`${pageHead('My Profile','Personal details that you can keep up to date.',`<button class="primary" data-action="edit-profile">Edit allowed fields</button>`)}<section class="detail-top"><div class="photo">${initials(e.employee_name)}</div><div><h2>${escape(e.employee_name||'Your profile')}</h2><p>${escape(e.designation||'Employee')} · ${escape(e.department||'')}</p></div></section>${documentSection('Personal',[['Email',e.user_id||e.company_email],['Phone',e.cell_number],['Address',e.current_address],['Profile picture',e.image?'Uploaded':'Not uploaded']])}${documentSection('Employment (managed by HR)',[['Employee ID',e.name],['Department',e.department],['Designation',e.designation],['Joining date',date(e.date_of_joining)],['Reporting manager',e.reports_to]])}`,'My Profile')}
function reportsPage(){return shell(`${pageHead('Reports','Attendance, leave and payroll reporting from live records.')}<div class="layout-2 grid">${panel('Attendance',`<div class="panel-body"><button class="secondary wide" data-action="report">Daily attendance</button><button class="secondary wide" style="margin-top:8px" data-action="report">Weekly trend</button><button class="secondary wide" style="margin-top:8px" data-action="report">Status distribution</button></div>`)}${panel('Leave',`<div class="panel-body"><button class="secondary wide" data-action="report">Leave utilization</button><button class="secondary wide" style="margin-top:8px" data-action="report">Pending requests</button></div>`)}${panel('Payroll',`<div class="panel-body"><button class="secondary wide" data-nav="payroll">Salary summary</button><button class="secondary wide" style="margin-top:8px" data-nav="payroll">Salary slips</button></div>`)}</div>`,'Reports')}
async function notificationsPage(){ if(!state.data.notificationsLoaded){try{const r=await resource('Notification Log',{fields:['name','subject','email_content','creation','read','document_type','document_name'],limit_page_length:50});state.data.notifications=r.data||r;state.data.notificationsLoaded=true;state.data.unread=(state.data.notifications||[]).filter(n=>!n.read).length}catch(e){state.data.notificationsError=e.message}}const items=state.data.notifications||[];return shell(`${pageHead('Notifications','Updates that need your attention.',`<button class="secondary" data-action="read-all">Mark all read</button>`)}${panel('All notifications',items.length?`<div class="panel-body">${items.map(n=>`<div class="activity"><i class="dot"></i><div><b>${escape(n.subject)}</b><br/><small>${date(n.creation)} · ${n.read?'Read':'Unread'}</small></div></div>`).join('')}</div>`:empty(state.data.notificationsError||'No notifications.'))}`,'Notifications')}
function settingsPage(){return shell(`${pageHead('Settings','Frontend preview preferences.')}<section class="doc-section"><h3>Preview mode</h3><div class="notice">Dayflow is currently running as a self-contained frontend prototype. Its local sample records exist only to demonstrate the UI; no backend project is connected.</div></section>`,'Settings')}
function renderPage(){if(!state.user)return authView(); if(state.page.startsWith('employee/'))return detailPage(decodeURIComponent(state.page.slice(9))); if(state.page==='dashboard')return dashboard(); if(state.page==='employees')return employeesPage();if(state.page==='profile')return profilePage();if(state.page==='attendance')return attendancePage();if(state.page==='leave')return leavePage();if(state.page==='payroll')return payrollPage();if(state.page==='reports'&&roleIsHR())return reportsPage();if(state.page==='notifications')return notificationsPage();if(state.page==='settings'&&roleIsHR())return settingsPage();return dashboard()}
function render(){root.innerHTML=renderPage()}

function dialog(title,body,submitLabel='Save'){state.modal=`<div class="modal-backdrop"><form class="dialog" id="dialog-form"><div class="dialog-head"><h2>${title}</h2><button type="button" class="ghost" data-action="close-modal">×</button></div><div class="dialog-body">${body}</div><div class="dialog-foot"><button type="button" class="secondary" data-action="close-modal">Cancel</button><button class="primary">${submitLabel}</button></div></form></div>`;render()}
function addEmployeeDialog(){dialog('Add employee',`<div class="two"><div class="field"><label>First name *</label><input name="first_name" required /></div><div class="field"><label>Last name</label><input name="last_name" /></div></div><div class="two"><div class="field"><label>Company email *</label><input type="email" name="company_email" required /></div><div class="field"><label>Joining date *</label><input type="date" name="date_of_joining" required /></div></div><div class="two"><div class="field"><label>Department</label><input name="department" /></div><div class="field"><label>Designation</label><input name="designation" /></div></div><div class="field"><label>Employment type</label><input name="employment_type" value="Full-time" /></div>`,'Create employee');state.dialogKind='employee'}
function leaveDialog(){dialog('Apply for leave',`<div class="field"><label>Leave type *</label><select name="leave_type" required><option>Paid Leave</option><option>Sick Leave</option><option>Unpaid Leave</option></select></div><div class="two"><div class="field"><label>From date *</label><input required type="date" name="from_date" /></div><div class="field"><label>To date *</label><input required type="date" name="to_date" /></div></div><div class="field"><label>Remarks</label><textarea name="description" rows="3"></textarea></div>`,'Submit request');state.dialogKind='leave'}
function profileDialog(){const e=state.employee||{};dialog('Edit allowed profile fields',`<div class="field"><label>Phone</label><input name="cell_number" value="${escape(e.cell_number||'')}" /></div><div class="field"><label>Address</label><textarea name="current_address" rows="4">${escape(e.current_address||'')}</textarea></div><div class="field"><label>Profile picture URL</label><input name="image" value="${escape(e.image||'')}" /></div>`,'Save changes');state.dialogKind='profile'}
async function submitDialog(form){const data=Object.fromEntries(new FormData(form));try{if(state.dialogKind==='employee')await api('/api/resource/Employee',{method:'POST',body:JSON.stringify(data)});if(state.dialogKind==='leave')await api('/api/resource/Leave%20Application',{method:'POST',body:JSON.stringify({...data,employee:state.employee?.name})});if(state.dialogKind==='profile')await api(`/api/resource/Employee/${encodeURIComponent(state.employee.name)}`,{method:'PUT',body:JSON.stringify(data)});state.modal=null;state.data={};notify('Saved successfully.');render()}catch(e){const old=form.querySelector('.error');old?.remove();form.querySelector('.dialog-body').insertAdjacentHTML('afterbegin',`<div class="error">${escape(e.message)}</div>`)} }
async function signIn(form){const values=Object.fromEntries(new FormData(form));const error=root.querySelector('#auth-error');await pause();if(values.usr === DEMO_LOGIN.email && values.pwd === DEMO_LOGIN.password){state.role='HR';state.user='Aarav Mehta';state.employee=store.employees[0];state.data={};navigate('dashboard');return}const person=store.employees.find(employee=>employee.company_email===values.usr);if(person && values.pwd==='Dayflow@123'){state.role='Employee';state.user=person.employee_name;state.employee=person;state.data={};navigate('dashboard');return}error.innerHTML='<div class="error">Use the pre-filled demo account, or sign in with a created demo account.</div>'}
async function signUp(form){const values=Object.fromEntries(new FormData(form));const good=/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\w\s]).{12,}$/.test(values.password);const error=root.querySelector('#auth-error');if(!good){error.innerHTML='<div class="error">Use 12+ characters including upper-case, lower-case, number and symbol.</div>';return}if(store.employees.some(employee=>employee.name===values.employee_id || employee.company_email===values.email)){error.innerHTML='<div class="error">That Employee ID or email is already used in this preview.</div>';return}await pause();const user={name:values.employee_id,employee_name:values.email.split('@')[0].replace(/[._-]/g,' '),department:'Unassigned',designation:'Employee',status:'Active',date_of_joining:new Date().toISOString().slice(0,10),company_email:values.email,cell_number:'',current_address:'',employment_type:'Full-time'};store.employees.push(user);state.role=values.role;state.user=user.employee_name;state.employee=user;state.data={};navigate('dashboard');notify('Preview account created.')}
root.addEventListener('click', event => {
  const nav = event.target.closest('[data-nav]')
  if (nav) { navigate(nav.dataset.nav); return }
  const action = event.target.closest('[data-action]')?.dataset.action
  if (!action) return
  if (action === 'menu') { state.menu = !state.menu; render() }
  if (action === 'profile-menu') { state.menu = state.menu === 'profile' ? false : 'profile'; render() }
  if (action === 'logout') { state.user=null; state.employee=null; state.data={}; navigate('login') }
  if (action === 'add-employee') addEmployeeDialog()
  if (action === 'apply-leave') leaveDialog()
  if (action === 'edit-profile') profileDialog()
  if (action === 'close-modal') { state.modal=null; render() }
  if (action === 'filter') notify('Use column search or configure Frappe list filters on the server.')
  if (action === 'read-all') method('hrms.api.mark_all_notifications_as_read').then(() => { state.data.notificationsLoaded=false; notify('Notifications marked as read.'); render() }).catch(error => notify(error.message))
  if (action === 'report') notify('Select a report in the connected Frappe reporting workspace.')
})
root.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='signin')signIn(event.target);if(event.target.id==='signup')signUp(event.target);if(event.target.id==='dialog-form')submitDialog(event.target)})
root.addEventListener('input',event=>{if(!event.target.matches('[data-search]'))return;const value=event.target.value.toLowerCase();root.querySelectorAll('tbody tr[data-open]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(value))})
root.addEventListener('click',event=>{const row=event.target.closest('tr[data-open]');if(row&&row.dataset.open==='employees')navigate(`employee/${encodeURIComponent(row.dataset.id)}`)})
window.addEventListener('hashchange',()=>{state.page=location.hash.slice(1)||'dashboard';render()})
render()
boot()
